@staticmethod
def _validate_min_hit_rate_drop(
    min_hit_rate_drop: Any,
) -> tuple[int, int]:
    """Validate the minimum hit-rate drop threshold.

    Used only by
    :meth:`lifetime_churn_forecast_drift_wave_prediction_scorecard_regressions`,
    before any state lookup: ``min_hit_rate_drop`` must be a tuple
    (else :class:`TypeError`) of exactly two non-``bool``
    :class:`int` values (a ``bool`` or non-:class:`int` element
    raises :class:`TypeError`); a wrong element count, a negative
    numerator, a non-positive denominator or a numerator exceeding
    the denominator raises :class:`ValueError`.
    """
    if not isinstance(min_hit_rate_drop, tuple):
        raise TypeError(
            f"min_hit_rate_drop must be a tuple, got "
            f"{type(min_hit_rate_drop).__name__}"
        )
    if len(min_hit_rate_drop) != 2:
        raise ValueError(
            f"min_hit_rate_drop must have exactly 2 elements, got "
            f"{len(min_hit_rate_drop)}"
        )
    numerator, denominator = min_hit_rate_drop
    for position, part in enumerate(min_hit_rate_drop):
        name = f"min_hit_rate_drop[{position}]"
        if isinstance(part, bool) or not isinstance(part, int):
            raise TypeError(
                f"{name} must be an int, got {type(part).__name__}"
            )
    if numerator < 0:
        raise ValueError(
            "min_hit_rate_drop numerator must be non-negative"
        )
    if denominator < 1:
        raise ValueError(
            "min_hit_rate_drop denominator must be positive"
        )
    if numerator > denominator:
        raise ValueError(
            "min_hit_rate_drop numerator must not exceed the "
            "denominator"
        )
    return (numerator, denominator)

@staticmethod
def _validate_regression_wave_min_hit_rate_drop(
    regression_wave_min_hit_rate_drop: Any,
) -> tuple[int, int]:
    """Validate the regression wave minimum hit-rate drop threshold.

    Used only by
    :meth:`lifetime_churn_forecast_drift_wave_prediction_scorecard_regression_wave_forecast_scorecard_regressions`,

def _build_lifetime_churn_forecast_drift_wave_prediction_scorecard_regression_wave_forecast_scorecard_regression_wave_forecast_backtests_scorecards_regression_wave_forecast_backtests_scorecards_regressions_streaks_result(
    backtest_records: tuple[dict[str, object], ...],
    scorecards: tuple[tuple[object, ...], ...],
    regression_wave_regression_wave_regression_wave_baseline_splits: tuple[int, ...],
    regression_wave_regression_wave_regression_wave_min_evaluated_delta: int,
    regression_wave_regression_wave_regression_wave_min_hit_rate_drop: tuple[int, int],
    regression_wave_regression_wave_regression_wave_regression_limit: int,
    regression_wave_regression_wave_regression_wave_min_consecutive_splits: int,
    regression_wave_regression_wave_regression_wave_regression_streak_limit: int,
) -> dict[str, object]:
    """Connect per-split deepest scorecard regressions into streaks.

    Used only by
    :meth:`lifetime_churn_forecast_drift_wave_prediction_scorecard_regression_wave_forecast_scorecard_regression_wave_forecast_backtests_scorecards_regression_wave_forecast_backtests_scorecards_regressions_streaks`.
    The records are the complete, already-bounded ``backtests``
    tuple of
    :meth:`_build_lifetime_churn_forecast_drift_wave_prediction_scorecard_regression_wave_forecast_scorecard_regression_wave_forecast_backtests_scorecards_regression_wave_forecast_backtests_result`
    and the scorecards the already-bounded ``scorecards`` tuple of
    :meth:`_build_lifetime_churn_forecast_drift_wave_prediction_scorecard_regression_wave_forecast_scorecard_regression_wave_forecast_backtests_scorecards_regression_wave_forecast_backtests_scorecards_result`.
    Each requested split position reruns
    :meth:`_build_lifetime_churn_forecast_drift_wave_prediction_scorecard_regression_wave_forecast_scorecard_regression_wave_forecast_backtests_scorecards_regression_wave_forecast_backtests_scorecards_regressions_result`
    on the same frozen backtest records and scorecards with
    ``regression_wave_regression_wave_regression_wave_baseline_cutoffs``
    set to that position's value, so the position's kept regression
    set, thresholds and
    ``regression_wave_regression_wave_regression_wave_regression_limit``
    enforcement are exactly the single-split query's. An identity
    present in the regression records of two adjacent requested
    positions belongs to one run; an identity absent from any
    requested position ends its run there. Only runs of at least
    ``regression_wave_regression_wave_regression_wave_min_consecutive_splits``
    positions are kept, and only each identity's longest run
    survives, ties broken by the smaller start split and then the
    larger worst drop.

    Each kept record is a fresh dict with keys ordered ``identity,
    start_baseline_cutoffs, end_baseline_cutoffs, split_count,
    first_regression_cutoff, worst_rate_drop``: the run's first
    and last requested split values, the run length in positions,
    the smallest ``first_regression_cutoff`` over the run and the
    largest ``rate_drop`` over the run as a reduced
    ``(numerator, denominator)`` integer tuple (fractions compared
    by integer cross-multiplication, never dividing). Records sort
    by ``split_count`` descending, then ``worst_rate_drop``
    descending, then the identity in Unicode code point order. The
    complete qualifying set is built before
    ``regression_wave_regression_wave_regression_wave_regression_streak_limit``
    is enforced, so an over-limit query raises :class:`ValueError`
    without truncating. ``totals`` is a fresh dict ordered
    ``identities, streaks, regressing_splits``: the kept identity
    count, the kept streak count and the number of distinct
    requested split positions covered by the kept streaks; no
    qualifying streak yields an empty tuple and three zeros.
    Every record is built fresh and shares no mutable object with
    the backtest records or the scorecards.
    """
    per_split: list[dict[object, dict[str, object]]] = []
    for split in (
        regression_wave_regression_wave_regression_wave_baseline_splits
    ):
        point = BranchStore._build_lifetime_churn_forecast_drift_wave_prediction_scorecard_regression_wave_forecast_scorecard_regression_wave_forecast_backtests_scorecards_regression_wave_forecast_backtests_scorecards_regressions_result(
            backtest_records,
            scorecards,
            split,
            regression_wave_regression_wave_regression_wave_min_evaluated_delta,
            regression_wave_regression_wave_regression_wave_min_hit_rate_drop,
            regression_wave_regression_wave_regression_wave_regression_limit,
        )
        per_identity: dict[object, dict[str, object]] = {}
        for record in point["regressions"]:
            per_identity[record["identity"]] = record
        per_split.append(per_identity)

    active: dict[object, dict[str, object]] = {}
    started: list[dict[str, object]] = []
    for index, per_identity in enumerate(per_split):
        for identity, record in per_identity.items():
            run = active.get(identity)
            if run is None:
                run = {
                    "identity": identity,
                    "start_index": index,
                    "records": [],
                }
                active[identity] = run
                started.append(run)
            run["records"].append(record)
        for identity in list(active):
            if identity not in per_identity:
                del active[identity]

    def drop_exceeds(
        left: tuple[int, int], right: tuple[int, int]
    ) -> bool:
        # Both drops have positive denominators, so integer
        # cross-multiplication orders them without dividing.
        return left[0] * right[1] > right[0] * left[1]

    best_by_identity: dict[object, dict[str, object]] = {}
    for run in started:
        records = run["records"]
        if (
            len(records)
            < regression_wave_regression_wave_regression_wave_min_consecutive_splits
        ):
            continue
        worst_rate_drop = records[0]["rate_drop"]
        first_regression_cutoff = records[0][
            "first_regression_cutoff"
        ]
        for record in records[1:]:
            if drop_exceeds(record["rate_drop"], worst_rate_drop):
                worst_rate_drop = record["rate_drop"]
            if (
                record["first_regression_cutoff"]
                < first_regression_cutoff
            ):
                first_regression_cutoff = record[
                    "first_regression_cutoff"
                ]
        streak = {
            "identity": run["identity"],
            "start_baseline_cutoffs": (
                regression_wave_regression_wave_regression_wave_baseline_splits[
                    run["start_index"]
                ]
            ),
            "end_baseline_cutoffs": (
                regression_wave_regression_wave_regression_wave_baseline_splits[
                    run["start_index"] + len(records) - 1
                ]
            ),
            "split_count": len(records),
            "first_regression_cutoff": first_regression_cutoff,
            "worst_rate_drop": worst_rate_drop,
        }
        identity = run["identity"]
        incumbent = best_by_identity.get(identity)
        if incumbent is None:
            best_by_identity[identity] = streak
            continue
        if streak["split_count"] != incumbent["split_count"]:
            if streak["split_count"] > incumbent["split_count"]:
                best_by_identity[identity] = streak
            continue
        if (
            streak["start_baseline_cutoffs"]
            != incumbent["start_baseline_cutoffs"]
        ):
            if (
                streak["start_baseline_cutoffs"]
                < incumbent["start_baseline_cutoffs"]
            ):
                best_by_identity[identity] = streak
            continue
        if drop_exceeds(
            streak["worst_rate_drop"], incumbent["worst_rate_drop"]
        ):
            best_by_identity[identity] = streak

    streaks = list(best_by_identity.values())

    def compare_streaks(
        left: dict[str, object], right: dict[str, object]
    ) -> int:
        if left["split_count"] != right["split_count"]:
            return (
                -1
                if left["split_count"] > right["split_count"]
                else 1
            )
        if drop_exceeds(
            left["worst_rate_drop"], right["worst_rate_drop"]
        ):
            return -1
        if drop_exceeds(
            right["worst_rate_drop"], left["worst_rate_drop"]
        ):
            return 1
        left_key = BranchStore._lifetime_identity_unicode_key(
            left["identity"]
        )
        right_key = BranchStore._lifetime_identity_unicode_key(
            right["identity"]
        )
        if left_key < right_key:
            return -1
        if left_key > right_key:
            return 1
        return 0

    streaks.sort(key=functools.cmp_to_key(compare_streaks))

    if (
        len(streaks)
        > regression_wave_regression_wave_regression_wave_regression_streak_limit
    ):
        raise ValueError(
            f"lifetime churn drift wave prediction scorecard "
            f"regression wave forecast scorecard regression wave "
            f"forecast backtest scorecard regression wave forecast "
            f"backtest scorecard regression streak limit exceeded: "
            f"{len(streaks)} streaks, limit is "
            f"{regression_wave_regression_wave_regression_wave_regression_streak_limit}"
        )

    split_seen: set[object] = set()
    totals = {"identities": 0, "streaks": 0, "regressing_splits": 0}
    for streak in streaks:
        totals["identities"] += 1
        totals["streaks"] += 1
        for index in range(
            regression_wave_regression_wave_regression_wave_baseline_splits.index(
                streak["start_baseline_cutoffs"]
            ),
            regression_wave_regression_wave_regression_wave_baseline_splits.index(
                streak["end_baseline_cutoffs"]
            )
            + 1,
        ):
            split_seen.add(
                regression_wave_regression_wave_regression_wave_baseline_splits[
                    index
                ]
            )
    totals["regressing_splits"] = len(split_seen)
    return {"streaks": tuple(streaks), "totals": totals}

