    "worst_rate_drop": (2, 3),
}, streak
assert result["totals"] == {"identities": 1, "streaks": 1, "regressing_splits": 2}
print("builder connect OK")

# 3. Gap breaks the run; min_consecutive_splits filters.
result = build_streaks(gap_records("B"), kept_scorecards("B"), (1, 2, 3), 0, (1, 2), 50, 1, 50)
assert len(result["streaks"]) == 1
assert result["streaks"][0]["split_count"] == 1
assert result["streaks"][0]["start_reference_cutoffs"] == 1
assert result["totals"] == {"identities": 1, "streaks": 1, "regressing_splits": 1}
