    return getattr(store, STREAKS_QUERY)(**merged)

for bad in (True, 1, 1.0, "1", None, [1, 2], (True, 1), (1.0, 2)):
    try:
        call(**{f"{PREFIX}_baseline_splits": bad})
    except TypeError:
        pass
    else:
